class Config:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance.settings = {}
        return cls._instance

c1 = Config()
c2 = Config()
c1.settings['theme'] = 'dark'
print(c1 is c2)

class EventEmitter:
    def __init__(self):
        self.listeners = {}

    def on(self, event, callback):
        self.listeners.setdefault(event, []).append(callback)

    def emit(self, event, data=None):
        for callback in self.listeners.get(event, []):
            callback(data)

def log_login(user):
    print(f'[log] {user} logged in')

def greet(user):
    print(f'Welcome back, {user}!')

emitter = EventEmitter()
emitter.on('login', log_login)
emitter.on('login', greet)
emitter.emit('login', 'alice')
emitter.emit('logout', 'alice')

class Circle:
    def area(self):
        return 'circle area'

class Square:
    def area(self):
        return 'square area'

class Triangle:
    def area(self):
        return 'triangle area'

class ShapeFactory:
    _registry = {'circle': Circle, 'square': Square, 'triangle': Triangle}

    @classmethod
    def create(cls, shape_type):
        shape_class = cls._registry.get(shape_type.lower())
        if shape_class is None:
            raise ValueError(f'Unknown shape type: {shape_type}')
        return shape_class()

for kind in ['circle', 'Square', 'triangle']:
    shape = ShapeFactory.create(kind)
    print(type(shape).__name__, '->', shape.area())

try:
    ShapeFactory.create('hexagon')
except ValueError as e:
    print(e)

def bubble_sort(data):
    data = data[:]
    for i in range(len(data) - 1):
        for j in range(len(data) - 1 - i):
            if data[j] > data[j + 1]:
                data[j], data[j + 1] = data[j + 1], data[j]
    return data

def quick_sort(data):
    if len(data) <= 1:
        return data
    pivot = data[0]
    less = [x for x in data[1:] if x < pivot]
    more = [x for x in data[1:] if x >= pivot]
    return quick_sort(less) + [pivot] + quick_sort(more)

class Sorter:
    def __init__(self, strategy):
        self.strategy = strategy

    def sort(self, data):
        return self.strategy(data)

numbers = [5, 2, 9, 1, 7]
sorter = Sorter(strategy=bubble_sort)
print('bubble:', sorter.sort(numbers))

sorter.strategy = quick_sort
print('quick: ', sorter.sort(numbers))

class Coffee:
    def cost(self):
        return 2.00

    def description(self):
        return 'Coffee'

class MilkDecorator:
    def __init__(self, coffee):
        self._coffee = coffee

    def cost(self):
        return self._coffee.cost() + 0.50

    def description(self):
        return self._coffee.description() + ', milk'

class SugarDecorator:
    def __init__(self, coffee):
        self._coffee = coffee

    def cost(self):
        return self._coffee.cost() + 0.25

    def description(self):
        return self._coffee.description() + ', sugar'

plain = Coffee()
with_milk = MilkDecorator(plain)
fancy = SugarDecorator(MilkDecorator(Coffee()))

for drink in [plain, with_milk, fancy]:
    print(f'{drink.description()}: {drink.cost():.2f}')

